from abc import ABCMeta, abstractmethod

import attr
import six
from typing import List, Optional  # noqa: F401

from .pdu import PduPort  # noqa: F401


@six.add_metaclass(ABCMeta)
class Attenuator(object):

    @abstractmethod
    def __init__(self, ip_addr,
                 port,
                 attenuation_port_numbers,
                 model=None,
                 version=None,
                 serial_number=None,
                 pdu_port=None):
        # type: (str, int, List[int], Optional[str], Optional[str], Optional[str], Optional[PduPort]) -> None
        """

        :param str ip_addr: IP ADDRESS
        :param int port: attenuator's port for management
        :param List[int] attenuation_port_numbers: List of Port numbers on the attenuator
        :param Optional[str] model: model of the Attenuator, e.g. "TAS16T16-51-120-1SDES"
        :param Optional[str] version: version of the Attenuator, e.g. "0.2"
        :param Optional[str] serial_number: serial number of the Attenuator, e.g. "30020100080"
        :param Optional[PduPort] pdu_port: PduPort class instance object
        """
        self.ip_addr = ip_addr
        self.port = port
        self.attenuator_ports = {i: AttenuationPort(self, i) for i in attenuation_port_numbers}
        self.attenuation_port_numbers = attenuation_port_numbers
        self.model = model
        self.version = version
        self.serial_number = serial_number
        self.pdu_port = pdu_port


@attr.s(cmp=False)
class AttenuationPort(object):
    """

    :param Attenuator attenuator: object of subclass of AttenuationPort
    :param int port_no: Port/Outlet number on the attenuator
    """
    attenuator = attr.ib(type=Attenuator)
    port_no = attr.ib(type=int)


class TopYoung(Attenuator):
    def __init__(self, **kwargs):
        super(TopYoung, self).__init__(**kwargs)
        self.vendor = "TOPYOUNG"


class HBTE(Attenuator):
    def __init__(self, **kwargs):
        super(HBTE, self).__init__(**kwargs)
        self.vendor = "HBTE"


class Hytem(Attenuator):
    def __init__(self, **kwargs):
        super(Hytem, self).__init__(**kwargs)
        self.vendor = "HYTEM"


class RadioRack(Attenuator):
    def __init__(self, **kwargs):
        super(RadioRack, self).__init__(**kwargs)
        self.vendor = "RADIORACK"


class JFW(Attenuator):
    def __init__(self, mode=None, **kwargs):
        """

        :param mode: operation mode of the attenuator
        """
        super(JFW, self).__init__(**kwargs)
        self.mode = mode or 'ports'
        self.vendor = "JFW"


class Eubus(Attenuator):
    def __init__(self, **kwargs):
        super(Eubus, self).__init__(**kwargs)
        self.vendor = "Eubus"
